function validateOrderLinesData(data: any): boolean {
  if (!Array.isArray(data)) return false;
  for (const line of data) {
    if (typeof line !== 'object' || line === null) return false;
    // Exemplo de campos esperados: productId (string), quantity (number), price (number)
    if (typeof line.productId !== 'string') return false;
    if (typeof line.quantity !== 'number' || line.quantity <= 0) return false;
    if (typeof line.price !== 'number' || line.price < 0) return false;
  }
  return true;
}

