import path from 'path'
import express from 'express'

const router = express.Router()
const LOGS_DIR = path.resolve('logs') // diretório base fixo

// whitelist de caracteres permitidos no nome do arquivo
const FILE_NAME_REGEX = /^[a-zA-Z0-9_\-\.]+$/

router.get('/log/:file', (req, res, next) => {
  const file = req.params.file

  // 1. Validação básica: tamanho máximo e whitelist de caracteres
  if (!file || file.length > 255 || !FILE_NAME_REGEX.test(file)) {
    res.status(400)
    return next(new Error('Invalid file name'))
  }

  // 2. Construir caminho absoluto usando path.join (evita concatenação insegura)
  const filePath = path.join(LOGS_DIR, file)

  // 3. Garantir que o caminho resultante esteja dentro do diretório base
  const resolvedPath = path.resolve(filePath)
  if (!resolvedPath.startsWith(LOGS_DIR + path.sep)) {
    res.status(403)
    return next(new Error('Access to the requested file is forbidden'))
  }

  // 4. Enviar o arquivo de forma segura
  res.sendFile(resolvedPath, err => {
    if (err) {
      // Se o arquivo não existir ou outro erro, delega ao middleware de erro
      next(err)
    }
  })
})

export default router

